 const auditIDs={"modal":"auditReviewDialog","modalTitle":"auditReviewTitle","modalBody":"auditReviewBody","modalFooter":"auditReviewFooter","closeModal":"auditReviewClose","teacherAdmin":"auditWheel"}; const $=id=>document.getElementById(auditIDs[id]||id),escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 let api,notes={},unlocked=false,capturing=false,captureQueued=false,job=null,dbPromise=null,scheduled=false,editorPosition=null,editorDrag=null;const memory=new Map();const epochKey='math-landing:assessment:teacher-audit-epoch';let auditEpoch=localStorage.getItem(epochKey)||'0',auditRevision=0,clearing=false,auditSelection=null;
 try{notes=JSON.parse(localStorage.getItem(key)||'{}')}catch{}
 try{unlocked=sessionStorage.getItem(sessionKey)==='yes'}catch{}
 function flagged(){return Object.values(notes).filter(n=>n.flagged).sort((a,b)=>a.created.localeCompare(b.created))}
