async function eraseImages(id=null){const ids=id===null?null:Array.isArray(id)?id:[id];if(ids===null)memory.clear();else ids.forEach(k=>memory.delete(k));const db=await database();await new Promise((resolve,reject)=>{const tx=db.transaction('pages','readwrite'),store=tx.objectStore('pages');if(ids===null)store.clear();else ids.forEach(k=>store.delete(k));tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}
async function clearAudit(id=null){if(!unlocked||clearing)return;const multiple=Array.isArray(id);if(multiple&&!id.length)return;clearing=true;invalidateCaptures();if(id===null){for(const note of Object.values(notes))clearNote(note);notes={};}else{for(const k of multiple?id:[id]){if(notes[k])clearNote(notes[k]);delete notes[k];}}persist();refresh();try{await eraseImages(id);if(id===null||multiple){dashboard();api.toast(id===null?'Audit cleared. Print audit 0 · Excel 0.':id.length+' selected audit page'+(id.length===1?'':'s')+', PNGs and notes cleared.')}else{$('modal').close();api.toast('This audit page, PNG and notes cleared.')}}catch{api.toast('Audit entries cleared, but this browser could not remove the saved PNGs.')}finally{clearing=false;refresh();if($('teacherAdminClearFlags'))updateClearSelection();}}
