 function positionEditor(left,top){const dialog=$('modal'),r=dialog.getBoundingClientRect();left=Math.max(8,Math.min(left,innerWidth-r.width-8));top=Math.max(8,Math.min(top,innerHeight-r.height-8));dialog.style.left=left+'px';dialog.style.top=top+'px';editorPosition={left,top}}
 function resetEditor(){const dialog=$('modal'),header=dialog.querySelector('.modal-header');editorDrag=null;delete dialog.dataset.auditEditorId;dialog.classList.remove('audit-floating','audit-collapsed');dialog.style.removeProperty('left');dialog.style.removeProperty('top');header.onpointerdown=header.onpointermove=header.onpointerup=header.onpointercancel=null;$('modalTitle').onkeydown=null;$('modalTitle').removeAttribute('tabindex');$('modalTitle').removeAttribute('aria-label');$('teacherAuditMinimize')?.remove();header.querySelector('.audit-move-hint')?.remove()}
