 function database(){if(!dbPromise)dbPromise=new Promise((resolve,reject)=>{const request=indexedDB.open('math-landing-assessment-teacher-audit',1);request.onupgradeneeded=()=>request.result.createObjectStore('pages',{keyPath:'id'});request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)});return dbPromise}
