 return {lock,editCurrent:toggle,review:dashboard,requestAccess:login,acceptPasscode:code=>{if(code!=='5160')return false;unlocked=true;sessionStorage.setItem(sessionKey,'yes');refresh();return true},reasonOptions:()=>reasons.slice(),init,backup,restore,exportExcel,resetEditor,isExporting:()=>!!job,cancelExport:()=>{if(job)job.cancel=true},refresh,flags:()=>flagged().map(n=>({...n,pageCode:n.pageCode||window.ML_PAGE_CODES?.forNote(n)})),isUnlocked:()=>unlocked};
